    ('45762448-5303-4e98-a999-e6aa22f63595'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd3-2026-10-02b-s004-rollback:45762448-5303-4e98-a999-e6aa22f63595:period_name', 'rollback of fields-wd3-2026-10-02b-s004: period_name None restored on Wilbury Hill Camp', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-700) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0119)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia dates the Wilbury Hill Camp hill fort west of Letchworth, Hertfordshire, to the late Bronze Age, about 700 BC; under the one-source rule the hedged year -700 stands.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
    ('45762448-5303-4e98-a999-e6aa22f63595'::uuid, 'period_start', '-700', NULL, 'fields-wd3-2026-10-02b-s004-rollback:45762448-5303-4e98-a999-e6aa22f63595:period_start', 'rollback of fields-wd3-2026-10-02b-s004: period_start None restored on Wilbury Hill Camp', '[{"source": "https://en.wikipedia.org/wiki/Wilbury_Hill_Camp", "url": "https://en.wikipedia.org/wiki/Wilbury_Hill_Camp", "quote": "Wilbury Hill Camp is a late Bronze Age (about 700 BC) hill fort west of Letchworth in Hertfordshire.", "outcome": "found"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0119)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia dates the Wilbury Hill Camp hill fort west of Letchworth, Hertfordshire, to the late Bronze Age, about 700 BC; under the one-source rule the hedged year -700 stands.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
    ('457ab845-d771-4c3d-8236-b9c57a0d2e43'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd3-2026-10-02b-s004-rollback:457ab845-d771-4c3d-8236-b9c57a0d2e43:period_name', 'rollback of fields-wd3-2026-10-02b-s004: period_name None restored on Celemantia', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0280)", "decision": "replace", "status": "MISSING", "reasoning": "The English Wikipedia article on Celemantia dates the start of the site, the construction of the Roman castellum, to the 2nd half of the 1st century AD, so the century that carries the start is the 1st century AD. As a century is entered as its first year, the value is 1, which falls in the 1-500 AD bucket; the source''s half-century hedge does not narrow the stored year further.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('457ab845-d771-4c3d-8236-b9c57a0d2e43'::uuid, 'period_start', '1', NULL, 'fields-wd3-2026-10-02b-s004-rollback:457ab845-d771-4c3d-8236-b9c57a0d2e43:period_start', 'rollback of fields-wd3-2026-10-02b-s004: period_start None restored on Celemantia', '[{"source": "https://en.wikipedia.org/wiki/Celemantia", "url": "https://en.wikipedia.org/wiki/Celemantia", "quote": "The construction of the castellum started in the 2nd half of the 1st century.", "outcome": "found"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0280)", "decision": "replace", "status": "MISSING", "reasoning": "The English Wikipedia article on Celemantia dates the start of the site, the construction of the Roman castellum, to the 2nd half of the 1st century AD, so the century that carries the start is the 1st century AD. As a century is entered as its first year, the value is 1, which falls in the 1-500 AD bucket; the source''s half-century hedge does not narrow the stored year further.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('45958d56-72b2-44e3-ada0-c7030f469445'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd3-2026-10-02b-s004-rollback:45958d56-72b2-44e3-ada0-c7030f469445:period_name', 'rollback of fields-wd3-2026-10-02b-s004: period_name None restored on Lopen Roman Mosaic', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(360) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0089)", "decision": "replace", "status": "MISSING", "reasoning": "The site is the Lopen Roman Mosaic; the Yeovil Archaeological and Local History Society''s chronicle on the Lopen and Dinnington Roman sites dates the Lopen villa''s fine mosaic pavement to c.360 AD (the same page has the villa occupied from the 3rd century AD, so the bucket 1 - 500 AD is the same either way).", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
    ('45958d56-72b2-44e3-ada0-c7030f469445'::uuid, 'period_start', '360', NULL, 'fields-wd3-2026-10-02b-s004-rollback:45958d56-72b2-44e3-ada0-c7030f469445:period_start', 'rollback of fields-wd3-2026-10-02b-s004: period_start None restored on Lopen Roman Mosaic', '[{"source": "https://www.yalhs.org.uk/2014-pg121-lopen-dinnington-roman-sites/", "url": "https://www.yalhs.org.uk/2014-pg121-lopen-dinnington-roman-sites/", "quote": "evidence of eight rooms was uncovered, including a fine mosaic pavement datable to c.360 AD.", "outcome": "found"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0089)", "decision": "replace", "status": "MISSING", "reasoning": "The site is the Lopen Roman Mosaic; the Yeovil Archaeological and Local History Society''s chronicle on the Lopen and Dinnington Roman sites dates the Lopen villa''s fine mosaic pavement to c.360 AD (the same page has the villa occupied from the 3rd century AD, so the bucket 1 - 500 AD is the same either way).", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
    ('4596b4ff-d2f3-4927-a4d8-461618570642'::uuid, 'site_type', 'Archaeological site', NULL, 'fields-wd3-2026-10-02b-s004-rollback:4596b4ff-d2f3-4927-a4d8-461618570642:site_type', 'rollback of fields-wd3-2026-10-02b-s004: site_type None restored on Archaeological Ensemble of Tárraco', '[{"source": "https://patrimoni.gencat.cat/en/collection/tarraco", "url": "https://patrimoni.gencat.cat/en/collection/tarraco", "quote": "The archaeological complex of Tarraco was declared a World Heritage Site in 2000", "outcome": "found"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0282)", "decision": "replace", "status": "MISSING", "reasoning": "The Cultural Heritage collection of the Government of Catalonia calls Tárraco an archaeological complex of Roman remains (walls, forums, circus, theatre, amphitheatre, necropolis, aqueduct, villas, quarry, mausoleum, arch) inscribed as a World Heritage Site. No canonical type for a multi-monument ensemble exists, and none of the listed specific types (wall, theatre, amphitheatre, forum, circus) holds for the ensemble as a whole, so the generic but correct type \"Archaeological site\" applies.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('45a26f12-c56f-4ebb-bc65-ba9488b84826'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd3-2026-10-02b-s004-rollback:45a26f12-c56f-4ebb-bc65-ba9488b84826:period_name', 'rollback of fields-wd3-2026-10-02b-s004: period_name None restored on Etruscan Pyramid of Bomarzo', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-700) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD3 decision (counted, round 1, wd3-r1-b0006)", "decision": "replace", "status": "MISSING", "reasoning": "The researchers'' own page on the Bomarzo pyramid states the rock has been used as a place of worship since the time of the Etruscans, between the seventh and sixth centuries BC, so the monument''s use as a site starts in the 7th century BC.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('45a26f12-c56f-4ebb-bc65-ba9488b84826'::uuid, 'period_start', '-700', NULL, 'fields-wd3-2026-10-02b-s004-rollback:45a26f12-c56f-4ebb-bc65-ba9488b84826:period_start', 'rollback of fields-wd3-2026-10-02b-s004: period_start None restored on Etruscan Pyramid of Bomarzo', '[{"source": "https://piramide-etrusca.it/category/articoli/news/", "url": "https://piramide-etrusca.it/category/articoli/news/", "quote": "The Etruscan pyramid of Bomarzo is the largest rock altar in Europe, a huge tufa rock used as a place of worship for sure since the time of the Etruscans between the seventh and sixth centuries BC", "outcome": "found"}, {"source": "WD3 decision (counted, round 1, wd3-r1-b0006)", "decision": "replace", "status": "MISSING", "reasoning": "The researchers'' own page on the Bomarzo pyramid states the rock has been used as a place of worship since the time of the Etruscans, between the seventh and sixth centuries BC, so the monument''s use as a site starts in the 7th century BC.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('45a26f12-c56f-4ebb-bc65-ba9488b84826'::uuid, 'site_type', 'Monument', NULL, 'fields-wd3-2026-10-02b-s004-rollback:45a26f12-c56f-4ebb-bc65-ba9488b84826:site_type', 'rollback of fields-wd3-2026-10-02b-s004: site_type None restored on Etruscan Pyramid of Bomarzo', '[{"source": "https://the-past.com/review/travel/bomarzo-and-its-pyramid/", "url": "https://the-past.com/review/travel/bomarzo-and-its-pyramid/", "quote": "an extraordinary monument", "outcome": "found"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0186)", "decision": "replace", "status": "MISSING", "reasoning": "World Archaeology (The Past) calls the so-called Pyramid of Bomarzo an extraordinary monument carved into the rock; the canonical list has no altar type, so Monument is the most specific fit.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
    ('45e80c0e-3eaf-4f57-8461-a821ef3ea096'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd3-2026-10-02b-s004-rollback:45e80c0e-3eaf-4f57-8461-a821ef3ea096:period_name', 'rollback of fields-wd3-2026-10-02b-s004: period_name None restored on Petriana', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(122) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0097)", "decision": "replace", "status": "MISSING", "reasoning": "The German Wikipedia article on Kastell Uxelodunum (Petriana, Stanwix, Carlisle) states that the first small timber-and-earth fort at Stanwix was built by the Romans around AD 122, so the start is AD 122.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
    ('45e80c0e-3eaf-4f57-8461-a821ef3ea096'::uuid, 'period_start', '122', NULL, 'fields-wd3-2026-10-02b-s004-rollback:45e80c0e-3eaf-4f57-8461-a821ef3ea096:period_start', 'rollback of fields-wd3-2026-10-02b-s004: period_start None restored on Petriana', '[{"source": "https://de.wikipedia.org/wiki/Kastell_Uxelodunum", "url": "https://de.wikipedia.org/wiki/Kastell_Uxelodunum", "quote": "Zuerst wurde von den Römern um 122 n. Chr. in Stanwix eine kleine Holz-Erde-Befestigung errichtet.", "outcome": "found"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0097)", "decision": "replace", "status": "MISSING", "reasoning": "The German Wikipedia article on Kastell Uxelodunum (Petriana, Stanwix, Carlisle) states that the first small timber-and-earth fort at Stanwix was built by the Romans around AD 122, so the start is AD 122.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
    ('4624b081-fd19-48f9-a93d-a6f74ede6c01'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd3-2026-10-02b-s004-rollback:4624b081-fd19-48f9-a93d-a6f74ede6c01:period_name', 'rollback of fields-wd3-2026-10-02b-s004: period_name None restored on Temple of Apollo, Melite', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(101) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0200)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia states the temple of Apollo at Melite is believed to have been built in the 2nd century AD, so the start is the first year of that century, 101.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
    ('4624b081-fd19-48f9-a93d-a6f74ede6c01'::uuid, 'period_start', '101', NULL, 'fields-wd3-2026-10-02b-s004-rollback:4624b081-fd19-48f9-a93d-a6f74ede6c01:period_start', 'rollback of fields-wd3-2026-10-02b-s004: period_start None restored on Temple of Apollo, Melite', '[{"source": "https://en.wikipedia.org/wiki/Temple_of_Apollo_(Melite)", "url": "https://en.wikipedia.org/wiki/Temple_of_Apollo_(Melite)", "quote": "It is believed to have been built in the 2nd century AD", "outcome": "found"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0200)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia states the temple of Apollo at Melite is believed to have been built in the 2nd century AD, so the start is the first year of that century, 101.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
    ('4656cc72-cea3-407e-a61c-314450ff6c62'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd3-2026-10-02b-s004-rollback:4656cc72-cea3-407e-a61c-314450ff6c62:period_name', 'rollback of fields-wd3-2026-10-02b-s004: period_name None restored on Ringsbury Camp', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-50) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD3 decision (counted, round 1, wd3-r1-b0003)", "decision": "replace", "status": "MISSING", "reasoning": "The English Wikipedia article states that the hill fort of Ringsbury Camp is thought to date from approximately the year 50 BC, a hedged year that the owner rule of 2026-10-01 counts, so the start is 50 BC. Purton Museum and the Heritage Gateway, which refuse automated requests, add only Iron Age, and the Atlas of Hillforts of Britain and Ireland could not be reached, so this is the one source that states a year. The later suggestion that the fort was the site of the Battle of Mount Badon in the late 5th or early 6th century concerns its use, not its construction.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('4656cc72-cea3-407e-a61c-314450ff6c62'::uuid, 'period_start', '-50', NULL, 'fields-wd3-2026-10-02b-s004-rollback:4656cc72-cea3-407e-a61c-314450ff6c62:period_start', 'rollback of fields-wd3-2026-10-02b-s004: period_start None restored on Ringsbury Camp', '[{"source": "https://en.wikipedia.org/wiki/Ringsbury_Camp", "url": "https://en.wikipedia.org/wiki/Ringsbury_Camp", "quote": "thought to date from approximately the year 50BC, in the civil parish of Purton in Wiltshire, England.", "outcome": "found"}, {"source": "WD3 decision (counted, round 1, wd3-r1-b0003)", "decision": "replace", "status": "MISSING", "reasoning": "The English Wikipedia article states that the hill fort of Ringsbury Camp is thought to date from approximately the year 50 BC, a hedged year that the owner rule of 2026-10-01 counts, so the start is 50 BC. Purton Museum and the Heritage Gateway, which refuse automated requests, add only Iron Age, and the Atlas of Hillforts of Britain and Ireland could not be reached, so this is the one source that states a year. The later suggestion that the fort was the site of the Battle of Mount Badon in the late 5th or early 6th century concerns its use, not its construction.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('47396b3b-88aa-4d18-a7ac-8bec4154c19d'::uuid, 'site_type', 'Archaeological site', NULL, 'fields-wd3-2026-10-02b-s004-rollback:47396b3b-88aa-4d18-a7ac-8bec4154c19d:site_type', 'rollback of fields-wd3-2026-10-02b-s004: site_type None restored on Wilca', '[{"source": "https://en.wikipedia.org/wiki/Wilca", "url": "https://en.wikipedia.org/wiki/Wilca", "quote": "is an archaeological site in Peru", "outcome": "found"}, {"source": "WD3 decision (counted, round 1, wd3-r1-b0008)", "decision": "replace", "status": "MISSING", "reasoning": "The English Wikipedia article states that Wilca, in the Cajaruro District of Utcubamba, Amazonas, ''is an archaeological site in Peru'', and the Spanish article agrees (''es un sitio arqueológico en Perú''). The Spanish text does describe ''este pequeño asentamiento'' of circular buildings and terraces, but no readable source states the type in a word the check can match, so the generic archaeological site is what a source stands behind.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
    ('473987c8-f684-4c4a-8c23-633821731f1e'::uuid, 'geom', 'SRID=4326;POINT(-4.768655 37.892469)', '0101000020E6100000311B8A33001113C0E0854426F6EE4240', 'fields-wd3-2026-10-02b-s004-rollback:473987c8-f684-4c4a-8c23-633821731f1e:geom', 'rollback of fields-wd3-2026-10-02b-s004: geom ''0101000020E6100000311B8A33001113C0E0854426F6EE4240'' restored on Roman Walls of Córdoba', '[{"source": "https://www.wikidata.org/wiki/Q15554384", "url": "https://www.wikidata.org/wiki/Q15554384", "quote": "37°53''32.89\"N, 4°46''7.18\"W", "outcome": "found"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0290)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Wikidata item of the Roman walls of Cordoba prints its coordinate location as 37°53''32.89\"N, 4°46''7.18\"W, which is 2.85 km from the stored point 37.86688688608024, -4.766602330498061, so the stored point cannot stand. Spanish Wikipedia prints the same point (37.8924700835, -4.76865541395) for its article on the walls of Cordoba, whose Roman first enclosure is described there as built in the 2nd century AD, and the point lies north of the Guadalquivir on the old Roman town, where the circuit ran.", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
